// a web-page extension is a web page, so there is nothing to fetch. An image
// extension proves nothing and is never trusted -- that URL is still fetched.
const path = (raw.match(/^[A-Za-z][A-Za-z0-9+.-]*:\/\/[^\/?#]*([^?#]*)/) || [])[1] || '';
